alimi.z-os.vip {

    # W208_PAPER_CONTROL_API_ROUTE
    handle /api/paper-control/command* {
        reverse_proxy 127.0.0.1:8792
    }

    encode gzip

    header {
        Cache-Control "no-store, no-cache, must-revalidate, max-age=0"
        X-ZEL-Alimi-Root "w130-caddy-var-www-z-os-alimi"
    }

    # Q4R3_EXACT25_VIEW_CONTRACT_ROUTE_BEGIN
    handle /api/view_contract_latest.json {
        root * /var/www/z-os-alimi/api
        rewrite * /view_contract_latest.json
        header Content-Type "application/json"
        header Cache-Control "no-store, no-cache, must-revalidate"
        file_server
    }
    # Q4R3_EXACT25_VIEW_CONTRACT_ROUTE_END
    handle_path /api/* {
        root * /var/www/z-os-alimi/api
        header Content-Type "application/json"
        file_server
    }

    handle_path /static/* {
        root * /var/www/z-os-alimi/static
        file_server
    }

    handle /paper_30d_canonical_ui_latest.json {
        root * /var/www/z-os-alimi/api
        rewrite * /paper_30d_canonical_ui_latest.json
        header Content-Type "application/json"
        file_server
    }

    handle /paper_30d_evaluation_status_latest.json {
        root * /var/www/z-os-alimi/api
        rewrite * /paper_30d_evaluation_status_latest.json
        header Content-Type "application/json"
        file_server
    }

    handle /paper_30d_evaluation_metrics_latest.json {
        root * /var/www/z-os-alimi/api
        rewrite * /paper_30d_evaluation_metrics_latest.json
        header Content-Type "application/json"
        file_server
    }

    handle /paper_performance_aggregator_latest.json {
        root * /var/www/z-os-alimi/api
        rewrite * /paper_performance_aggregator_latest.json
        header Content-Type "application/json"
        file_server
    }

    handle /paper_30d_perf_edge_latest.json {
        root * /var/www/z-os-alimi/api
        rewrite * /paper_30d_perf_edge_latest.json
        header Content-Type "application/json"
        file_server
    }

    handle {
        root * /var/www/z-os-alimi
        try_files {path} {path}/ /index.html
        file_server
    }

    # W221D_TV_OBSERVER_PROXY
    handle /api/tv/observe {
        reverse_proxy 127.0.0.1:8799
    }

}
